import java.util.List;

public class LargestSubstringFinder {
    public int findLargestSubstring(List<String> strings) {
        int maxLength = 0;
        for (int i = 0; i < strings.size(); i++) {
            for (int j = i + 1; j < strings.size(); j++) {
                String x = strings.get(i);
                String y = strings.get(j);
                if (containsSubstring(x, y) || containsSubstring(x.reverse(), y)) {
                    maxLength = Math.max(maxLength, Math.max(x.length(), y.length()));
                }
            }
        }
        return maxLength;
    }

    private boolean containsSubstring(String a, String b) {
        int index = a.indexOf(b);
        return index != -1;
    }

    private String reverse(String s) {
        char[] chars = s.toCharArray();
        for (int i = 0, j = chars.length - 1; i < j; i++, j--) {
            char temp = chars[i];
            chars[i] = chars[j];
            chars[j] = temp;
        }
        return new String(chars);
    }

    public static void main(String[] args) {
        LargestSubstringFinder finder = new LargestSubstringFinder();
        System.out.println(finder.findLargestSubstring(List.of("ABCD", "BCDFF", "BRCD"))); // Output: 2
        System.out.println(finder.findLargestSubstring(List.of("rose", "orchid"))); // Output: 2
    }
}
