 public static int countOilDeposits(char[][] grid) {
    int count = 0;
    int rows = grid.length;
    int cols = grid[0].length;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
                boolean[][] visited = new boolean[rows][cols];
                if (dfs(grid, i, j, visited)) {
                    count++;
                }
            }
        }
    }

    return count;
}

private static boolean dfs(char[][] grid, int i, int j, boolean[][] visited) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || visited[i][j]) {
        return false;
    }
    if (grid[i][j] == '*') {
        visited[i][j] = true;
        return true;
    }
    boolean[] directions = {0, 1, 0, -1, 0};
    for (int k = 0; k < 4; k++) {
        int x = i + directions[k];
        int y = j + directions[k + 1];
        if (dfs(grid, x, y, visited)) {
            return true;
        }
    }
    return false;
}
