public static int countOilDeposits(char[][] grid) {
    int count = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                int currentArea = bfs(i, j, grid);
                if (currentArea > 0) {
                    count++;
                }
            }
        }
    }
    return count;
}

private static int bfs(int x, int y, char[][]grid) {
    if (x < 0 || x >= grid.length || y < 0 || y >= grid[x].length || grid[x][y] != '@') {
        return 0;
    }

    grid[x][y] = '*'; // Mark as visited

    int[] dx = {0, 1, 0, -1};
    int[] dy = {1, 0, -1, 0};
    int area = 1;

    for (int i = 0; i < 4; i++) {
        int newX = x + dx[i];
        int newY = y + dy[i];
        int currentArea = bfs(newX, newY, grid);
        if (currentArea > 0) {
            area += currentArea;
        }
    }

    return area;
}
