public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    boolean[][] visited = new boolean[n][n];

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            visited[i][j] = false;
        }
    }

    return isReachable(n, start, end, paths, visited);
}

private static String isReachable(int n, int[] start, int[] end, int[][] paths, boolean[][] visited) {
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n) {
        return "cannot be travelled";
    }

    if (end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    visited[start[0]][start[1]] = true;

    for (int i = 0; i < paths.length; i++) {
        int x = paths[i][0];
        int y = paths[i][1];

        if (validMove(start, x, y)) {
            if (x == end[0] && y == end[1]) {
                return "can be travelled";
            }

            if (!visited[x][y]) {
                if (isReachable(n, new int[]{x, y}, end, paths, visited)) {
                    return "can be travelled";
                }
            }
        }
    }

    return "cannot be travelled";
}

private static boolean validMove(int[] current, int x, int y) {
    return (current[0] == x || current[1] == y) || (current[0] + 1 == x && current[1] == y) || (current[0] == x && current[1] + 1 == y);
}
