            visited.remove(nodes[i]);
        }
    }
    visited.add(x);
    visited.add(y);
    if (canTravelFrom(paths, visited, pathSet, x, y, targetX, targetY)) {
        return true;
    }
    visited.remove(nodes[i]);
    return false;
