    int commonLetters = 0;
    int length1 = word1.length();
    int length2 = word2.length();
    char[] word1Chars = word1.toCharArray();
    char[] word2Chars = word2.toCharArray();

    for (char c : word1Chars) {
        for (char c2 : word2Chars) {
            if (c == c2) {
                commonLetters++;
                break;
            }
        }
    }

    int gcd = gcd(commonLetters, length1 + length2);
    return "appx(\"" + word1 + "\", \"" + word2 + "\") = " + front(gcd, commonLetters) + "/" + front(gcd, length1 + length2);
}

private static int gcd(int a, int b) { // Compute gcd using Euclidean algorithm
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

private static String front(int value, int max) {
    return value <= max / 2 ? Integer.toString(value) : "-" + Integer.toString(value - max);
}
