public int minTime(int n, int[][] edges, boolean[] hasApple) {
    boolean[] visited = new boolean[n];
    // Union-Find algorithm to remove redundant edges
    for (int[] edge : edges) {
        union(visited, edge[0], edge[1]);
    }

    // Post-order traversal of the tree to update apple count
    return postOrder(visited, 0, hasApple);
}

private void Union(boolean[] visited, int p, int q) {
    int xp = find(visited, p);
    int xq = find(visited, q);
    if (xp == xq) return;
    visited[xp] = xq;
}

private int find(boolean[] visited, int x) {
    if (visited[x] != x) {
        visited[x] = find(visited, visited[x]);
    }
    return visited[x];
}

private int postOrder(boolean[] visited, int currentNode, boolean[] hasApple) {
    int totalTime = 0;
    for (int[] edge : edges) {
        if (edge[0] == currentNode) {
            totalTime += postOrder(visited, edge[1], hasApple);
            if (hasApple[edge[1]]) {
                totalTime += 2; // Incurs time for to visit both nodes and return
            }
        } else if (edge[1] == currentNode) {
            totalTime += postOrder(visited, edge[0], hasApple);
            if (hasApple[edge[0]]) {
                totalTime += 2; // Incurs time for to visit both nodes and return
            }
        }
    }
    return totalTime;
}
