    Map<Integer, List<Integer>> graph = buildGraph(n, edges);
    boolean[] visited = new boolean[n];
    return dfs(graph, visited, hasApple, 0, new int[1]);
}

private Map<Integer, List<Integer>> buildGraph(int n, int[][] edges) {
    Map<Integer, List<Integer>> graph = new HashMap<>();
    for (int[] edge : edges) {
        int u = edge[0], v = edge[1];
        graph.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
        graph.computeIfAbsent(v, k -> new ArrayList<>()).add(u);
    }
    return graph;
}

private int dfs(Map<Integer, List<Integer>> graph, boolean[] visited, boolean[] hasApple, int u, int[] dist) {
    visited[u] = true;
    int time = 0;
    for (int v : graph.getOrDefault(u, new ArrayList<>())) {
        if (!visited[v]) {
            int subTime = dfs(graph, visited, hasApple, v, dist);
            if (subTime > 0 || hasApple[v]) {
                time += subTime + 2;
            }
        }
    }
    dist[0] = Math.max(dist[0], time);
    return time;
}
