public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] time = new int[n];
    Map<Integer, List<Integer>> graph = new HashMap<>();
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        if (!graph.containsKey(u)) graph.put(u, new ArrayList<>());
        if (!graph.containsKey(v)) graph.put(v, new ArrayList<>());
        graph.get(u).add(v);
        graph.get(v).add(u);
    }

    boolean[] visited = new boolean[n];
    dfs(0, graph, hasApple, visited, time);
    return time[0];
}

private void dfs(int node, Map<Integer, List<Integer>> graph, boolean[] hasApple, boolean[] visited, int[] time) {
    visited[node] = true;
    for (int child : graph.get(node)) {
        if (!visited[child]) {
            dfs(child, graph, hasApple, visited, time);
            time[node] += time[child] + 2; // Add time to return to child
        }
    }
    // Check if node is an apple or has an apple as a parent
    if (hasApple[node] || hasApple[visited[node]]) {
        time[node]++;
    }
}
