public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    int left = 0, right = chars.length - 1;
    String result = "";
    while (left <= right) {
        if (left == right) {
            result += chars[left];
            break;
        }
        result += chars[left++];
        if (left == right) {
            result += chars[left];
            break;
        }
        result += chars[right--];
        if (left > right) {
            result += chars[left++];
        }
    }
    return result;
}
