    for (char c : s.toCharArray()) {
        counts[c]++;
    }

    StringBuilder result = new StringBuilder();
    int i = 0, j = 255;
    while (result.length() < s.length()) {
        appendSmallestChar(result, counts, i++);
        appendLargestChar(result, counts, j--);
    }

    return result.toString();
}

private void appendSmallestChar(StringBuilder result, int[] counts, int i) {
    while (i >= 0 && counts[i] == 0) {
        i--;
    }
    if (i < 0) return;

    counts[i]--;
    result.append((char) i);
}

private void appendLargestChar(StringBuilder result, int[] counts, int j) {
    while (j <= 255 && counts[j] == 0) {
        j++;
    }
    if (j >= 255) return;

    counts[j]--;
    result.append((char) j);
}
