        while (i < 128 && count[i] == 0) {
            i++;
        }
        if (i == 128) {
            break;
        }
        result.append((char) i);
        count[i]--;
        used[i] = true;

        i = 127;
        while (i >= 0 && count[i] == 0) {
            i--;
        }
        if (i == -1) {
            break;
        }
        result.append((char) i);
        count[i]--;
        used[i] = true;
    }

    return result.toString();
