public boolean splitArraySameAverage(int[] nums) {
    int totalSum = Arrays.stream(nums).sum();
    int length = nums.length;
    // Check if the total sum is possible to split into two equal averages
    if (totalSum % 2 != 0) {
        return false;
    }
    // Calculate the target average for each half of the array
    int targetAverage = totalSum / 2;
    // Check for the existence of a subarray that sums up to the target average
    return containsSubsetWithSum(targetAverage, nums);
}

private boolean containsSubsetWithSum(int targetSum, int[] nums) {
    Set<Integer> sumSet = new HashSet<>();
    sumSet.add(0); // Base case, sum list is trivially zero (empty subset)
    for (int num : nums) {
        sumSet.add(sumSet.contains(num) ? sumSet.getLast() + num : num);
        if (sumSet.contains(targetSum)) {
            return true; // Found valid subset
        }
    }
    return false; // No subset exists with the target sum
}
