            int[] left = new int[n / i], right = new int[n / i];
            for (int j = 0, k = 0; j < n; j++) {
                if (j % i == 0) {
                    left[k++] = nums[j];
                } else {
                    right[k++] = nums[j];
                }
            }
            if (sum(left) == sum(right)) {
