    // Check if the total sum is odd
    if (totalSum % 2 != 0) {
        return false;
    }

    // Calculate the average of the array
    double avg = (double) totalSum / nums.length;

    // Check if the average of two parts of the array is equal to the average
    for (int i = 0; i < nums.length; i++) {
        double part1Sum = Arrays.stream(nums, 0, i).sum();
        double part2Sum = Arrays.stream(nums, i + 1, nums.length).sum();
        if (2 * part1Sum == avg * nums.length) {
            return true;
        }
    }

    return false;
}
