public int uniqueMorseRepresentations(String[] words) {
    // Define the Morse codes for each letter of the alphabet
    String[] morse = {".-", "-...", "-.-.", "-..", ".", "..-.", "--.", "....", "..", ".---", "-.-", ".-..", "--", "..--", "...-", ".--", "---", "--.--", "---..", ".--.-", "--.--", "--..."};
