    HashMap<Character, String> morseMap = new HashMap<>();
    for (int i = 0; i < morse.length; i++) {
        morseMap.put((char) ('a' + i), morse[i]);
    }
    // Collect all unique Morse representations
    HashSet<String> uniqueRepresentations = new HashSet<>();
    for (String word : words) {
        StringBuilder morseWord = new StringBuilder();
        for (char c : word.toCharArray()) {
            morseWord.append(morseMap.get(c));
        }
        uniqueRepresentations.add(morseWord.toString());
    }
    // Return the number of unique Morse representations
    return uniqueRepresentations.size();
}
