import java.util.Set;
import java.util.HashSet;
import java.lang.Character;

public boolean hasAllCodes(String s, int k) {
    // Check if the length of the string is less than the length of the substring k
    if (s.length() < k) {
        return false;
    }

    // Convert the binary string to a set of its substrings of length k
    Set<String> substrings = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        substrings.add(s.substring(i, i + k));
    }

    // Check if the size of the set matches the number of possible combinations of length k
    return substrings.size() == (1 << k);
}
