    for (int n : nums) {
        totalSum += n;
        if (minSum < n) {
            minSum = n;
            result = Math.max(result, totalSum - minSum);
        } else {
            result = Math.max(result, totalSum);
        }
        if (maxSum > n) {
            maxSum = n;
        }
    }
