    int maxSum = 0, minSum = 0, maxAbsSum = 0;
    for (int num : nums) {
        maxSum = Math.max(num, maxSum + num);
        minSum = Math.min(num, minSum + num);
        maxAbsSum = Math.max(maxAbsSum, Math.max(maxSum, -minSum));
    }
    return maxAbsSum;
}
