        int nextFib = fibs.get(fibs.size() - 1) + fibs.get(fibs.size() - 2);
        if (nextFib > k) break;
        fibs.add(nextFib);
    }
    int count = 0;
    for (int i = fibs.size() - 1; i >= 0 && k > 0; i--) {
        while (fibs.get(i) <= k) {
            count++;
            k -= fibs.get(i);
        }
    }
