public int maxUniqueSplit(String s) {
    int result = 0;
    int length = s.length();
    int[] state = new int[1 << length];
    state[0] = 1;
    for (int i = 0; i < length; i++) {
        int mask = 1 << i;
        for (int from = 0; from < i; from++) {
            int leftMask = state[mask ^ (1 << from)];
            if (leftMask == 0) {
                continue;
            }
            int newMask = leftMask | mask;
            String substr = s.substring(from + 1, i + 1);
            if (!state[newMask]) {
                state[newMask] = 1;
                result++;
            }
        }
    }
    state[0] = -1; // defensive, don't forget to clear it to not cause troubles
    return result;
}
