public int maxUniqueSplit(String s) {
    int count = 1;
    int len = s.length();
    int maxLen = len;

    for (int i = 0, j = i + 1; j <= len; i++) {
        if (i == 0) {
            continue;
        }
        if (hasUniqueSubstring(s, i, j)) {
            count++;
        } else {
            j = i + 1;
        }
        maxLen = Math.max(maxLen, j - i);
    }

    return maxLen;
}

private boolean hasUniqueSubstring(String s, int start, int end) {
    Set<Character> set = new HashSet<>();
    for (int i = start; i < end; i++) {
        if (set.contains(s.charAt(i))) {
            return false;
        }
        set.add(s.charAt(i));
    }
    return true;
}
