public int maxUniqueSplit(String s) {
    int max = 0;
    for (int i = 1; i <= s.length(); i++) {
        String prefix = s.substring(0, i);
        if (isValidSplit(prefix, s)) {
            int remaining = maxUniqueSplit(s.substring(i));
            max = Math.max(max, 1 + remaining);
        }
    }
    return max;
}

private boolean isValidSplit(String prefix, String remainder) {
    if (prefix.equals(remainder)) {
        return true;
    }
    for (int i = 1; i <= remainder.length(); i++) {
        String suffix = remainder.substring(0, i);
        String rest = remainder.substring(i);
        HashSet<String> set = new HashSet<>();
        set.add(prefix);
        if (set.add(suffix) && isValidSplit(rest, suffix)) {
            return true;
        }
    }
    return false;
}
