public String getSmallestString(int n, int k) {
    if (n == 0) return "";
    String res = "";
    int a = 0, f = 0;
    while (n > 0) {
        for (a = 0; a < 26; a++) {
            if (k - (a + 1) * n < 0) continue;
            f = 1;
            d = k - (a + 1) * n;
        }
        if (f == 1) {
            res = res + (char) ('a' + (a));
            k = d;
            n = n - 1;
        }
    }
    return res;
}
