public static double calculateProbability(int n) {
    double[][] dp = new double[n + 1][n + 1];
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= n; j++) {
            if (i == j) {
                dp[i][j] = 1.0;
            } else {
                dp[i][j] = Double.NaN;
            }
        }
    }
    for (int i = 2; i <= n; i++) {
        for (int j = 0; j <= i - 2; j++) {
            dp[i][j] = dp[j + 1][i - 2] * 0.5 + dp[j][i - 1] * 0.5;
        }
        dp[i][i - 1] = 1.0;
    }
    return dp[n][n - 1];
}
