import java.util.List;

public class SteppingFinder {
    public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> steppingNumbers = new java.util.ArrayList<>();
        // Ensure low is at least 0
        if (low < 0) {
            low = 0;
        }

        for (int num = low; num <= high; num++) {
            if (isStepping(num)) {
                steppingNumbers.add(num);
            }
        }
        steppingNumbers.sort(null);
        return steppingNumbers;
    }

    private static boolean isStepping(int num) {
        int lastDigit = num;
        while (num > 0) {
            int currentDigit = num % 10;
            if (currentDigit == lastDigit - 1 || currentDigit == lastDigit + 1) {
                lastDigit = currentDigit;
            } else {
                return false;
            }
            num /= 10;
        }
        return true;
    }
}
