public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    Queue<Integer> q = new LinkedList<>();
    if (low <= 0) {
        q.add(0);
    }
    while (!q.isEmpty()) {
        int num = q.poll();
        if (num >= low && num <= high) {
            result.add(num);
        }
        int d = num % 10;
        if (d > 0) {
            q.add(num * 10 + d - 1);
        }
        if (d < 9) {
            q.add(num * 10 + d + 1);
        }
    }
    Collections.sort(result);
    return result;
