import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

public static class SteppingNumberFinder {

    public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> steppingNumbers = new ArrayList<>();
        LinkedList<Integer> queue = new LinkedList<>();

        // Add the number 0 and 1 to the queue
        for (int num : new int[]{0, 1}) {
            queue.add(num);
            steppingNumbers.add(num);
        }

        // Process each number in the queue
        while (!queue.isEmpty()) {
            int current = queue.poll();
            int prev = current < 0 ? 0 : current % 10;
            int next = prev + 1;

            // Generate the next number
            if (next < 10 && !(current != 0 && next == 0)) {
                int nextNumber = current * 10 + next;
                queue.add(nextNumber);
                steppingNumbers.add(nextNumber);
            }

            // Generate the previous number
            if (prev > 0 && prev != 9 && !(current != 0 && prev == 8)) {
                int nextNumber = current * 10 + (prev - 1);
                queue.add(nextNumber);
                steppingNumbers.add(nextNumber);
            }
        }

        // Filter the stepping numbers in the given range
        steppingNumbers.stream()
                      .filter(num -> num >= low && num <= high)
                      .sorted()
                      .collect(Collectors.toList());
        return steppingNumbers;
    }

    public static void main(String[] args) {
        System.out.println(findSteppingNumbers(0, 21));
        System.out.println(findSteppingNumbers(30, 100));
    }
}
