public static int countDigitOne(int n) {
    String numStr = Integer.toString(n) + "9";
    int ten = 1;
    int prev = 0;
    int count = 0;

    for (int i = 0; i < numStr.length(); i++) {
        int curr = (numStr.charAt(i) - '0') * ten;
        if (numStr.charAt(i) == '1') {
            count += count1InRange(n, 0, curr - 1) + (n - ten * 9);
        } else if (numStr.charAt(i) > '1') {
            count += count1InRange(n, 0, prev);
        }
        prev = curr;
        ten *= 10;
    }

    return count;
}

