public static int countDigitOne(int n) {
    int onesCount = 0;
    int i = 1;

    while (i <= n) {
        int onesInCurrent = i / 10; // Count the ones in the current ten's place
        onesCount += onesInCurrent * (i % 10); // Add the ones counted in the current ten's place
        int onesInCurrentTens = i / 100; // Count the ones in the current hundred's place
        onesCount += onesInCurrentTens * Math.min(i % 100, 9); // Add the ones counted in the current hundred's place
        i *= 10;
    }

    return onesCount;
}
