public static boolean isPowerOfTwo(int n) {
    if (n <= 0) {
        return false;
    }
    // Check if n is a power of two by repeatedly dividing by 2 until n becomes 1
    while (n != 1) {
        if (n % 2 != 0) {
            return false;
