    for (int i = 0; i < m; i++) {
        int currentRowMaxLength = 0;
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                currentRowMaxLength++;
            } else {
                currentRowMaxLength = 0;
            }
            maxLengths[i][j] = currentRowMaxLength;
            maxLength = Math.max(maxLength, currentRowMaxLength);
        }
    }

    // Calculate the maximum length for vertical lines
    for (int j = 0; j < n; j++) {
        int currentColumnMaxLength = 0;
        for (int i = m - 1; i >= 0; i--) {
            if (mat[i][j] == 1) {
                currentColumnMaxLength++;
            } else {
                currentColumnMaxLength = 0;
            }
            maxLengths[i][j] += currentColumnMaxLength;
            maxLength = Math.max(maxLength, currentColumnMaxLength);
        }
    }

    // Calculate the maximum length for diagonal lines
    for (int i = -m + 1; i < n; i++) {
        int currentDiagonalMaxLength = 0;
        int row = i;
        int col = 0;
        while (row >= 0 && col < n) {
            if (mat[row][col] == 1) {
                currentDiagonalMaxLength++;
            } else {
                currentDiagonalMaxLength = 0;
            }
            maxLengths[row][col] += currentDiagonalMaxLength;
            row++;
            col++;
            maxLength = Math.max(maxLength, currentDiagonalMaxLength);
        }
    }

    // Calculate the maximum length for anti-diagonal lines
    for (int i = m; i >= -n; i--) {
        int currentAntiDiagonalMaxLength = 0;
