public int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLen = 0;

    // Check horizontal lines
    for (int i = 0; i < m; i++) {
        int count = 0;
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                count++;
            } else {
                maxLen = Math.max(maxLen, count);
                count = 0;
            }
        }
        maxLen = Math.max(maxLen, count);
    }

    // Check vertical lines
    for (int j = 0; j < n; j++) {
        int count = 0;
        for (int i = 0; i < m; i++) {
            if (mat[i][j] == 1) {
                count++;
            } else {
                maxLen = Math.max(maxLen, count);
                count = 0;
            }
        }
        maxLen = Math.max(maxLen, count);
    }

    // Check diagonal lines
    for (int i = 0, j = 0; i < m && j < n; i++, j++) {
        int count = 1;
        while (i + 1 < m && j + 1 < n && mat[i + 1][j + 1] == 1) {
            count++;
            i++;
            j++;
        }
        maxLen = Math.max(maxLen, count);
    }

    // Check anti-diagonal lines
    for (int i = 0, j = n - 1; i < m && j >= 0; i++, j--) {
        int count = 1;
        while (i + 1 < m && j - 1 >= 0 && mat[i + 1][j - 1] == 1) {
            count++;
            i++;
            j--;
        }
        maxLen = Math.max(maxLen, count);
    }

    return maxLen;
}
