public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) return 0;

    int rows = mat.length;
    int cols = mat[0].length;
    int[][][] dp = new int[4][rows][cols];

    int maxLength = 0;

    for (int c = 0; c < cols; c++) {
        dp[0][0][c] = 1;
        if (mat[0][c] == 1) maxLength = 1;
    }

    for (int r = 1; r < rows; r++) {
        dp[0][r][0] = 1;
        if (mat[r][0] == 1) maxLength = Math.max(maxLength, 1);
    }

    for (int c = 1; c < cols; c++) {
        dp[0][0][c] = 1;
        if (mat[0][c] == 1) maxLength = Math.max(maxLength, 1);
    }

    for (int r = 1; r < rows; r++) {
        dp[0][r][0] = 1;
        if (mat[r][0] == 1) maxLength = Math.max(maxLength, 1);
    }

    for (int r = 1; r < rows; r++) {
        for (int c = 1; c < cols; c++) {
            if (mat[r][c] == 1) {
                dp[0][r][c] = Math.max(Math.max(dp[0][r - 1][c], dp[1][r - 1][c - 1]), dp[2][r][c - 1]) + 1;
                maxLength = Math.max(maxLength, dp[0][r][c]);
            }
        }
    }

    return maxLength;
