import java.util.*;

class SquarePermutations {
    public static int squarePermutations(int[] A) {
        int n = A.length;
        if (n % 2 != 0) {
            return 0;
        }

        Map<Integer, Integer> elementCount = new HashMap<>();
        for (int num : A) {
            elementCount.put(num, elementCount.getOrDefault(num, 0) + 1);
        }

        List<Integer> set = new ArrayList<>(elementCount.keySet());
        int size = set.size();
        boolean[] picked = new boolean[size];
        int[] permutation = new int[size];

        int permutations = 0;
        backtrack(permutation, picked, size, set, permutation.length, elementCount);
        return permutations;
    }

    private static void backtrack(int[] permutation, boolean[] picked, int[] size, List<Integer> set, int target, int[] elementCount) {
        if (size == 0) {
            permutations++;
            return;
        }

        for (int i = 0; i < size; i++) {
            if (elementCount[set.get(i)] > 0) {
                picked[i] = true;
                permutation[size - 1] = set.get(i);
                int nextTarget = target - set.get(i);
                if (nextTarget % 2 == 0 && nextTarget >= 0) {
                    backtrack(permutation, picked, size - 1, set, nextTarget / 2, elementCount);
                }
                picked[i] = false;
            }
        }
    }
}
