import java.util.List;

public static int squarePermutations(int[] A) {
  List<int[]> result = new List<>();
  dfs(A, new int[A.length], result, new boolean[A.length]);
  return result.size();
}

private static void dfs(int[] A, int[] current, List<int[]> result, boolean[] used) {
  if (current.length == A.length) {
    result.add(current.clone());
    return;
  }
  for (int i = 0; i < A.length; i++) {
    if (!used[i] && isValid(current, A[i])) {
      used[i] = true;
      current[current.length] = A[i];
      dfs(A, current, result, used);
      used[i] = false;
    }
  }
}

private static boolean isValid(int[] current, int num) {
  int midSquare = midSquare(num);
  return midSquare * midSquare == num;
}

private static int midSquare(int num) {
  return (int) Math.sqrt(num);
}
