import java.util.Collections;

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n % 2 != 0) {
        return 0;
    }
    long[] factors = new long[n];
    for (int i = 0; i < n; i++) {
        if (A[i] > 0) {
            factors[i] = (long)Math.sqrt(A[i]);
            A[i] = (int)factors[i];
            if (factors[i] != A[i]) {
                return 0;
            }
        } else {
            continue;
        }
    }
    Arrays.sort(factors);
    return calculateSquarePermutations(factors);
}

private static int calculateSquarePermutations(long[] factors) {
    int n = factors.length;
    if (n == 0 || n == 1) {
        return isPermutation(factors) ? 1 : 0;
    }
    int result = 0;
    int[] permutations = new int[n];
    for (int i = 0; i < n; i++) {
        if (factors[i] != i + 1) {
            int temp = factors[i];
            factors[i] = i + 1;
            permutations[i] = temp;
            result += calculateSquarePermutations(factors);
            factors[i] = temp;
            permutations[i] = 1;
        }
    }
    return result;
}

private static boolean isPermutation(long[] factors) {
    Arrays.sort(factors);
    for (int i = 1; i < factors.length; i++) {
        if (factors[i] != i + 1) {
            return false;
        }
    }
    return true;
}
