public static int squarePermutations(int[] A) {
    int n = A.length;
    int[] visited = new int[n];
    List<int[]> permutations = new ArrayList<>();

    // Helper function to check if the sum of two numbers is a perfect square
    boolean isSquare(int a) {
        int sqrt = (int)Math.sqrt(a);
        return sqrt * sqrt == a;
    }

    // Perform backtracking
    backtrack(permutations, visited, A, new ArrayList<>());

    return permutations.size();
}

private static void backtrack(List<int[]> permutations, int[] visited, int[] A, List<Integer> current) {
    if (current.size() == A.length) {
        permutations.add(new ArrayList<>(current));
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (i > 0 && A[i] == A[i - 1] && !visited[i - 1]) continue;
        if (visited[i]) continue;

        if (isSquare(A[i] + current.get(current.size() - 1))) {
            visited[i] = true;
            current.add(A[i]);
            backtrack(permutations, visited, A, current);
            current.remove(current.size() - 1);
            visited[i] = false;
        }
    }
}
