public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    int[] leftSmallerIndexes = computeLeftSmallerIndexes(heights);
    int[] rightSmallerIndexes = computeRightSmallerIndexes(heights);

    for (int i = 0; i < heights.length; i++) {
        int width = rightSmallerIndexes[i] - leftSmallerIndexes[i] - 1;
        int area = heights[i] * width;
        maxArea = Math.max(maxArea, area);
    }

    return maxArea;
}

private static int[] computeLeftSmallerIndexes(int[] heights) {
    int[] leftSmallerIndexes = new int[heights.length];
    Arrays.fill(leftSmallerIndexes, heights.length);

    Stack<Integer> stack = new Stack<>();
    for (int i = 0; i < heights.length; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            int index = stack.pop();
            leftSmallerIndexes[index] = i;
        }
        stack.push(i);
    }

    return leftSmallerIndexes;
}

private static int[] computeRightSmallerIndexes(int[] heights) {
    int[] rightSmallerIndexes = new int[heights.length];
    Arrays.fill(rightSmallerIndexes, -1);

    Stack<Integer> stack = new Stack<>();
    for (int i = heights.length - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            int index = stack.pop();
            rightSmallerIndexes[index] = i;
        }
        stack.push(i);
    }

    return rightSmallerIndexes;
}
