public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];

    int[] offset = new int[]{0, 1};
    int index = 0;

    for (int i = 0; i < rows + cols - 1; i++) {
        int x = i / offset[0];
        int y = i % offset[1];

        int cnt = Math.abs(cols - y) - Math.abs(rows - x);
        if (cnt == x) {
            x--;
            y++;
        }
        result[index++] = mat[x][y];

        offset = shift(offset, index);
    }

    return result;
}

private static int[] shift(int[] offset, int index) {
    if (offset[0] == offset[1]) {
        offset[0]++;
    } else if (offset[1] == 0) {
        offset[1]++;
    } else if (offset[0] == 0) {
        offset[0]++;
    } else {
        offset[1]--;
    }

    return offset;
}
