    List<Integer> result = new ArrayList<>();
    int i = 0, j = 0;

    while (i < m && j < n) {
        result.add(mat[i][j]);
        if (i == j) {
            i++;
            j++;
        } else if (i == m - 1 || j == 0) {
            if (i == m - 1) {
                j++;
            } else {
                i++;
            }
        } else {
            i++;
            j--;
        }
    }

    int[] traversalArray = new int[result.size()];
    for (int k = 0; k < result.size(); k++) {
        traversalArray[k] = result.get(k);
    }

    return traversalArray;
}
