public static int findSmallestInteger(int n) {
    String s = String.valueOf(n);
    if (s.length() == 1) return n;

    char[] arr = s.toCharArray();
    Arrays.sort(arr);

    for (int i = arr.length - 1; i > 0; i--) {
        if (arr[i] > arr[i - 1]) {
            char[] temp = arr.clone();
            char tempMax = temp[i-1];
            for (int j = i - 1; j < arr.length; j++) {
                if (temp[j] < tempMax) {
                    swap(temp, i-1, j);
                    Arrays.sort(temp, i, temp.length);
                    return Integer.parseInt(new String(temp));
                }
            }
            break;
        }
    }

    return -1;
}

private static void swap(char[] arr, int i, int j) {
    char temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
