public int findSmallestInteger(int n) {
    // Convert the integer to a string
    String numStr = String.valueOf(n);
    int length = numStr.length();

    // Check if it's already the smallest possible number
    if (length == 1) return -1;

    // Try to find the smallest permutation greater than n
    for (int i = length - 2; i >= 0; i--) {
        if (numStr.charAt(i) < numStr.charAt(i + 1)) {
            // Find the smallest digit to swap with
            char charAtI = numStr.charAt(i);
            for (int j = i + 1; j < length; j++) {
                if (charAtI < numStr.charAt(j) && numStr.charAt(j) > numStr.charAt(i + 1)) {
                    // Swap the digits
                    numStr = swap(numStr, i, j);
                    // Sort the remaining digits to ensure the smallest possible number
                    String sortedNumStr = sort(numStr.substring(i + 2));
                    numStr = numStr.substring(0, i) + charAtI + sortedNumStr;
                    return Integer.parseInt(numStr);
                }
            }
        }
    }
    return -1;
}

private String sort(String str) {
    char[] array = str.toCharArray();
   Arrays.sort(array);
    return new String(array);
}

private String swap(String str, int i, int j) {
    char temp = str.charAt(i);
    str = str.substring(0, i) + str.charAt(j) + str.substring(i + 1);
    return str;
}
