public class Solution {
    public static int findSmallestInteger(int n) {
        if (n <= 10) {
            return -1; // All numbers greater than or equal to 10 have at least two digits
        }

        String numStr = String.valueOf(n);
        char[] charArray = numStr.toCharArray();
        Arrays.sort(charArray);

        // Find the first non-increasing digit from the right
        int i = charArray.length - 1;
        while (i > 0 && charArray[i - 1] <= charArray[i]) {
            i--;
        }

        if (i == 0) {
            return -1; // The input number is the largest number with n digits
        }

        // Find the smallest digit greater than charArray[i - 1] from the right
        int j = charArray.length - 1;
        while (charArray[j] <= charArray[i - 1]) {
            j--;
        }

        // Swap charArray[i - 1] and charArray[j]
        char temp = charArray[i - 1];
        charArray[i - 1] = charArray[j];
        charArray[j] = temp;

        // Sort the characters after the pivot index
        Arrays.sort(charArray, i, charArray.length);

        // Convert the array back to an integer
        return Integer.parseInt(new String(charArray));
    }
}
