public List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    // Since symmetry only matters at odd length, we only consider odd n
    // The first digit (center of symmetry) can't be '0' for any length
    for (int d = 1; d <= 9; d++) {
        if (n == 1) {
            result.add(String.valueOf(d));
            continue;
        }
        StringBuilder sb = new StringBuilder();
        // For odd n, the first and last digit are the same
        sb.append(d).append(centerSymmetricNumbers((int)Math.ceil(n/2)-1)).append(d);
        result.add(sb.toString());
    }
    return result;
}
