public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    // Calculate the slopes of the lines formed by the points
    double slope1 = (y1 - y2) / (x1 - x2);
    double slope2 = (y2 - y3) / (x2 - x3);
    double slope3 = (y3 - y1) / (x3 - x1);

    // Check if the slopes are all different
    return slope1 != slope2 && slope1 != slope3 && slope2 != slope3;
}
