private static int[] uglyNumbers = {1, 2, 3, 4, 5, 6, 8, 9, 10};
private static int currIndex = 0;

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return 0;
    }

    if (currIndex >= uglyNumbers.length) {
        currIndex = 0;
        int[] newUglyNumbers = new int[n];
        for (int i = 0; i < n; i++) {
            newUglyNumbers[i] = uglyNumbers[currIndex];
        }
        int[] updatedUglyNumbers = newUglyNumbers;
        currIndex = 0;
        for (int i = 0; i < updatedUglyNumbers.length; i++) {
            if (updatedUglyNumbers[i] != uglyNumbers[currIndex]) {
                if (updatedUglyNumbers[i] % 2 == 0) {
                    updatedUglyNumbers[i] /= 2;
                } else if (updatedUglyNumbers[i] % 3 == 0) {
                    updatedUglyNumbers[i] /= 3;
                } else if (updatedUglyNumbers[i] % 5 == 0) {
                    updatedUglyNumbers[i] /= 5;
                } else {
                    updatedUglyNumbers[i] = updatedUglyNumbers[currIndex] + 1;
                }
                updatedUglyNumbers[++currIndex] = updatedUglyNumbers[i];
            }
        }
        uglyNumbers = updatedUglyNumbers;
    }

    return uglyNumbers[currIndex];
}
