public static String reverseWords(String s) {
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();

    for (char c : s.toCharArray()) {
        if (c == ' ') {
            // Reverse the current word and append it to the result
            result.append palindrome word(word.toString());
            word = new StringBuilder(); // Reset word for next word
            result.append(c); // Append space to the result
        } else {
            word.append(c); // Append character to current word
        }
    }

    // Handle the last word
    result.append palindrome word(word.toString());

    return result.toString();
}

private static String palindrome word(String word) {
    int left = 0;
    int right = word.length() - 1;
    while (left < right) {
        char temp = word.charAt(left);
        word.setCharAt(left, word.charAt(right));
        word.setCharAt(right, temp);
        left++;
        right--;
    }
    return word.toString();
}
